// AUTO-GENERATED by Orca editor. Do not edit.
// Regenerated whenever the Debug Panel is saved, the project is opened, or main.orca changes.
//
// Authored in the Orca editor via "View > Debug Panel" and persisted to
// `main.orca.debugOptions`. Deliberately DECOUPLED from the game's own
// `IDebugData` / `IDebugOption` types so a diverged `models/debug.ts` can
// never turn this generated file into a compile error.

import { eventEmitter } from '@game-studio/arcade-base';

export interface OrcaDebugTicketOption {
    name: string;
    data: Record<string, unknown>;
}

export interface OrcaDebugEventButton {
    name: string;
    eventName: string;
}

export interface OrcaDebugModelPropertyChoice {
    label: string;
    target: 'gameModel' | 'settingsModel';
    propertyName: string;
    value: unknown;
}

export interface OrcaDebugModelPropertySetting {
    name: string;
    choices: OrcaDebugModelPropertyChoice[];
}

export interface OrcaDebugServerPatch {
    op: 'set' | 'push' | 'cells';
    path: string;
    value: unknown;
    cells?: Array<[number, number]>;
    count?: number | '$value';
    random?: boolean;
}

export interface OrcaDebugServerSetting {
    id: string;
    name: string;
    control: 'enum' | 'slider';
    choices?: Array<{ id: string; label: string; patches: OrcaDebugServerPatch[] }>;
    min?: number;
    max?: number;
    step?: number;
    patches?: OrcaDebugServerPatch[];
}

export interface OrcaDebugServerSettingsGroup {
    id: string;
    name: string;
    base: Record<string, unknown>;
    settings: OrcaDebugServerSetting[];
}

export const ORCA_DEBUG_TICKET_OPTIONS: OrcaDebugTicketOption[] = [
    {
        name: 'Bonus',
        data: {
            ReelStops: [70, 34, 51, 70, 15]
        }
    }
];

export const ORCA_DEBUG_EVENT_BUTTONS: OrcaDebugEventButton[] = [];

export const ORCA_DEBUG_MODEL_PROPERTY_SETTINGS: OrcaDebugModelPropertySetting[] = [];

export const ORCA_DEBUG_SERVER_SETTINGS: OrcaDebugServerSettingsGroup[] = [];

/**
 * Orca: if `option` is one of the fire-a-custom-event buttons authored in the
 * Debug Panel, emit its event and return true (the caller must then return
 * early — such an option must NEVER become `selectedOption`). Returns false
 * for a normal ticket option.
 *
 * The event name is read from `option.orcaEventName` when present and
 * otherwise recovered by matching `option.name` against the table above, so
 * this still works if the debug view hands back a reconstructed object
 * rather than the exact reference it was given.
 */
export function orcaFireDebugEvent(option: { name?: string; orcaEventName?: string } | null | undefined): boolean {
    if (!option) return false;

    const name = typeof option.name === 'string' ? option.name : '';
    let eventName = typeof option.orcaEventName === 'string' ? option.orcaEventName.trim() : '';
    if (!eventName && name) {
        const match = ORCA_DEBUG_EVENT_BUTTONS.find((b) => b.name === name);
        if (match) eventName = match.eventName;
    }
    if (!eventName) return false;

    eventEmitter.emit(eventName as any);
    // Close the debug overlay, exactly as a normal ticket-option click does.
    eventEmitter.emit('POPUP_TOGGLE_DEBUG_OVERLAY' as any, false);
    return true;
}

/** In-game value of each server setting, keyed `<group id>/<setting id>`. */
const orcaServerSettingValues = new Map<string, number>();

function orcaServerSettingValue(group: OrcaDebugServerSettingsGroup, setting: OrcaDebugServerSetting): number {
    const fallback = setting.control === 'slider' ? (setting.min ?? 0) : 0;
    return orcaServerSettingValues.get(`${group.id}/${setting.id}`) ?? fallback;
}

/** The patches a setting applies at `value`, or null while it is off ("None" / its minimum). */
function orcaActiveServerPatches(setting: OrcaDebugServerSetting, value: number): OrcaDebugServerPatch[] | null {
    if (setting.control === 'slider') return value > (setting.min ?? 0) ? (setting.patches ?? []) : null;
    const choice = (setting.choices ?? [])[Math.round(value) - 1];
    return choice ? choice.patches : null;
}

/** The Debug Panel server settings, as entries for `DebugModel.debugSettingOptions`. */
export function orcaDebugServerSettingOptions(): Array<Record<string, unknown>> {
    const out: Array<Record<string, unknown>> = [];
    for (const group of ORCA_DEBUG_SERVER_SETTINGS) {
        for (const setting of group.settings) {
            const key = `${group.id}/${setting.id}`;
            const onChange = (s: { currentValue?: unknown }): void => {
                const value = Number(s?.currentValue);
                orcaServerSettingValues.set(key, Number.isFinite(value) ? value : 0);
            };
            if (setting.control === 'slider') {
                out.push({ name: setting.name, min: setting.min ?? 0, max: setting.max ?? 1, steps: setting.step ?? 1, currentValue: setting.min ?? 0, onChange, type: 'slider' });
            } else {
                out.push({ name: setting.name, availableValues: ['None', ...(setting.choices ?? []).map((c) => c.label)], currentValue: 0, onChange, type: 'enum' });
            }
        }
    }
    return out;
}

/** True while any server setting is switched on. */
export function orcaDebugServerDataActive(): boolean {
    return ORCA_DEBUG_SERVER_SETTINGS.some((group) => group.settings.some((setting) =>
        orcaActiveServerPatches(setting, orcaServerSettingValue(group, setting)) !== null));
}

/**
 * The server debug data the active settings compose: each group starts from
 * its base and applies its settings from the bottom of the list up, so a
 * setting higher in the list wins a value two of them write. List pushes
 * run afterwards, top to bottom, so pushed items keep the list order.
 */
export function orcaDebugServerData(): Record<string, unknown> {
    let data: Record<string, unknown> = {};
    for (const group of ORCA_DEBUG_SERVER_SETTINGS) {
        const active: Array<{ patches: OrcaDebugServerPatch[]; value: number }> = [];
        for (const setting of group.settings) {
            const value = orcaServerSettingValue(group, setting);
            const patches = orcaActiveServerPatches(setting, value);
            if (patches) active.push({ patches, value });
        }
        if (active.length === 0) continue;
        const payload = JSON.parse(JSON.stringify(group.base)) as Record<string, unknown>;
        for (let i = active.length - 1; i >= 0; i -= 1) {
            for (const patch of active[i].patches) if (patch.op !== 'push') orcaApplyServerPatch(payload, patch, active[i].value);
        }
        for (const entry of active) {
            for (const patch of entry.patches) if (patch.op === 'push') orcaApplyServerPatch(payload, patch, entry.value);
        }
        data = { ...data, ...payload };
    }
    return data;
}

function orcaSubstituteSliderValue(value: unknown, slider: number): unknown {
    if (value === '$value') return slider;
    if (Array.isArray(value)) return value.map((item) => orcaSubstituteSliderValue(item, slider));
    if (value && typeof value === 'object') {
        const out: Record<string, unknown> = {};
        for (const key of Object.keys(value as Record<string, unknown>)) out[key] = orcaSubstituteSliderValue((value as Record<string, unknown>)[key], slider);
        return out;
    }
    return value;
}

function orcaServerPathTokens(path: string): Array<string | number> {
    const tokens: Array<string | number> = [];
    for (const part of path.split('.')) {
        const match = /^([^[\]]+)((?:\[\d+\])*)$/.exec(part);
        if (!match) return [];
        tokens.push(match[1]);
        for (const index of match[2].match(/\d+/g) ?? []) tokens.push(Number(index));
    }
    return tokens;
}

function orcaApplyServerPatch(root: Record<string, unknown>, patch: OrcaDebugServerPatch, slider: number): void {
    const tokens = orcaServerPathTokens(patch.path);
    if (tokens.length === 0) return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let node: any = root;
    for (let i = 0; i < tokens.length - 1; i += 1) {
        const key = tokens[i];
        if (node[key] === null || typeof node[key] !== 'object') node[key] = typeof tokens[i + 1] === 'number' ? [] : {};
        node = node[key];
    }
    const last = tokens[tokens.length - 1];
    const value = orcaSubstituteSliderValue(patch.value, slider);
    if (patch.op === 'set') {
        node[last] = value;
        return;
    }
    if (!Array.isArray(node[last])) node[last] = [];
    const list = node[last] as unknown[];
    if (patch.op === 'push') {
        list.push(value);
        return;
    }
    const cells = [...(patch.cells ?? [])];
    if (patch.random) {
        for (let i = cells.length - 1; i > 0; i -= 1) {
            const j = Math.floor(Math.random() * (i + 1));
            [cells[i], cells[j]] = [cells[j], cells[i]];
        }
    }
    const count = patch.count === '$value' ? Math.round(slider) : (patch.count ?? cells.length);
    for (const [column, row] of cells.slice(0, Math.max(0, count))) {
        if (!Array.isArray(list[column])) list[column] = [];
        (list[column] as unknown[])[row] = value;
    }
}
